package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"runtime/debug"
	"strings"
	"testing"
	"time"
)

var fw = []string{"a", "b", "c", "users", "user", "x", "abc", "ab", "static", "js", "files", "download", "create", "edit", "active", "1", "2"}

func frandRoute(r *rand.Rand) string {
	n := 1 + r.Intn(5)
	parts := []string{}
	for i := 0; i < n; i++ {
		switch r.Intn(7) {
		case 0:
			parts = append(parts, ":"+string(rune('a'+r.Intn(4))))
		case 1:
			parts = append(parts, "*")
		default:
			parts = append(parts, fw[r.Intn(len(fw))])
		}
	}
	p := "/" + strings.Join(parts, "/")
	if r.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func frandPath(r *rand.Rand) string {
	n := r.Intn(6)
	parts := []string{}
	for i := 0; i < n; i++ {
		if r.Intn(7) == 0 {
			parts = append(parts, "")
		} else {
			parts = append(parts, fw[r.Intn(len(fw))])
		}
	}
	p := "/" + strings.Join(parts, "/")
	if r.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func ffind(e *Echo, method, path string, timeout time.Duration) (HandlerFunc, string, interface{}, []byte, bool) {
	ctx := e.NewContext(nil, nil)
	done := make(chan struct{})
	var pan interface{}
	var stack []byte
	go func() {
		defer func() {
			if rec := recover(); rec != nil {
				pan = rec
				stack = debug.Stack()
			}
			close(done)
		}()
		e.router.Find(method, path, ctx)
	}()
	select {
	case <-done:
		return ctx.Handler(), ctx.Path(), pan, stack, false
	case <-time.After(timeout):
		return nil, "", nil, nil, true
	}
}

func isNF(h HandlerFunc) bool {
	return h == nil || fmt.Sprintf("%p", h) == fmt.Sprintf("%p", NotFoundHandler)
}

func TestZZFuzzOracle(t *testing.T) {
	r := rand.New(rand.NewSource(42))
	iters := 30000
	bugs := 0
	for it := 0; it < iters && bugs < 20; it++ {
		nRoutes := 2 + r.Intn(7)
		routes := []string{}
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, frandRoute(r))
		}
		paths := []string{}
		for i := 0; i < 8; i++ {
			paths = append(paths, frandPath(r))
		}
		// isolation
		iso := make([]map[string]bool, len(routes))
		for i, rp := range routes {
			e := New()
			e.GET(rp, func(c Context) error { return nil })
			m := map[string]bool{}
			for _, p := range paths {
				h, _, pan, stack, hung := ffind(e, http.MethodGet, p, 3*time.Second)
				if pan != nil || hung {
					t.Errorf("SINGLE route=%q path=%q pan=%v hung=%v\n%s", rp, p, pan, hung, stack)
					bugs++
				}
				m[p] = !isNF(h)
			}
			iso[i] = m
		}
		e := New()
		for _, rp := range routes {
			e.GET(rp, func(c Context) error { return nil })
		}
		for _, p := range paths {
			h, cpath, pan, stack, hung := ffind(e, http.MethodGet, p, 3*time.Second)
			if hung {
				t.Errorf("HANG routes=%v path=%q", routes, p)
				bugs++
				continue
			}
			if pan != nil {
				t.Errorf("PANIC routes=%v path=%q: %v\n%s", routes, p, pan, stack)
				bugs++
				continue
			}
			var exp []string
			for i, rp := range routes {
				if iso[i][p] {
					exp = append(exp, rp)
				}
			}
			if len(exp) == 0 {
				if !isNF(h) {
					t.Errorf("WRONG(no route matches) routes=%v path=%q matched=%q", routes, p, cpath)
					bugs++
				}
			} else {
				if isNF(h) {
					t.Errorf("MISSED(should match %v) routes=%v path=%q", exp, routes, p)
					bugs++
				} else {
					ok := false
					for _, rp := range exp {
						if rp == cpath {
							ok = true
						}
					}
					if !ok {
						t.Errorf("WRONGROUTE(iso=%v) routes=%v path=%q matched=%q", exp, routes, p, cpath)
						bugs++
					}
				}
			}
		}
	}
	t.Logf("done iters=%d bugs=%d", iters, bugs)
}
EOF
