101	// Binding is done in following order: 1) path params; 2) query params; 3) request body. Each step COULD override previous
102	// step binded values. For single source binding use their own methods BindBody, BindQueryParams, BindPathParams.
103	func (b *DefaultBinder) Bind(i interface{}, c Context) (err error) {
104		if err := b.BindPathParams(c, i); err != nil {
105			return err
106		}
107		// Issue #1670 - Query params are binded only for GET/DELETE and NOT for usual request with body (POST/PUT/PATCH)
108		// Reasoning here is that parameters in query and bind destination struct could have UNEXPECTED matches and results due that.
109		// i.e. is `&id=1&lang=en` from URL same as `{"id":100,"lang":"de"}` request body and which one should have priority when binding.
110		// This HTTP method check restores pre v4.1.11 behavior and avoids different problems when query is mixed with body
111		if c.Request().Method == http.MethodGet || c.Request().Method == http.MethodDelete {
112			if err = b.BindQueryParams(c, i); err != nil {
