package echo

import (
	"reflect"
	"testing"
)

func TestTmpBindDataToMap(t *testing.T) {
	data := map[string][]string{"foo": {"1", "2"}}
	b := new(DefaultBinder)

	tests := []struct {
		name        string
		destination func() interface{}
		expect      interface{}
	}{
		{
			name:        "map[string][]string",
			destination: func() interface{} { return &map[string][]string{} },
			expect:      map[string][]string{"foo": {"1", "2"}},
		},
		{
			name:        "map[string]string",
			destination: func() interface{} { return &map[string]string{} },
			expect:      map[string]string{"foo": "1"},
		},
		{
			name:        "nil map[string][]string",
			destination: func() interface{} { var m map[string][]string; return &m },
			expect:      map[string][]string{"foo": {"1", "2"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dest := tt.destination()
			if err := b.bindData(dest, data, "form"); err != nil {
				t.Fatalf("bindData returned error: %v", err)
			}
			got := reflect.ValueOf(dest).Elem().Interface()
			if !reflect.DeepEqual(got, tt.expect) {
				t.Fatalf("got %#v, want %#v", got, tt.expect)
			}
		})
	}
}

